// Checkout conversion module: auto-apply best offer to convert zero paidEvents
const { getBestOffer } = require('./offer-engine');
const { logRevenueEvent } = require('./revenue-logger');

async function applyConversionOffer(session) {
  const offer = await getBestOffer(session);
  if (!offer) return null;
  // Apply offer to session
  session.appliedOffer = offer;
  // Log conversion event
  await logRevenueEvent({
    type: 'conversion',
    sessionId: session.id,
    offerId: offer.id,
    amount: offer.price,
    currency: 'USD',
    timestamp: new Date().toISOString()
  });
  return offer;
}

module.exports = { applyConversionOffer };
